a {
  color: inherit;
  text-underline-offset: 4px;
}
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
::selection {
  color: var(--background);
  background: var(--accent);
}
::-webkit-scrollbar {
  width: 5px;
}
::-webkit-scrollbar-thumb {
  background: var(--line);
  border-radius: 4px;
}
.popup {
  padding: 16px;
}
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
  margin-bottom: 16px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 15px;
  font-weight: 750;
  letter-spacing: -0.025em;
}
.brand-mark {
  flex-shrink: 0;
  color: var(--accent);
}
.tab-button {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
}
.tab-button:hover {
  color: var(--accent);
  background: var(--surface);
}
.input-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 6px 6px 10px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 9px;
  transition: border-color 160ms ease-out;
}
.input-wrap:focus-within {
  border-color: var(--accent);
  outline: 1px solid var(--accent);
}
.input-wrap:has([aria-invalid="true"]) {
  border-color: var(--error);
}
.input-icon {
  flex-shrink: 0;
  color: var(--muted);
}
input {
  width: 100%;
  min-width: 0;
  padding: 4px 0;
  color: var(--ink);
  background: transparent;
  border: 0;
  outline: none;
  font-size: 12px;
  line-height: 20px;
  caret-color: var(--accent);
}
input::placeholder {
  color: var(--muted);
  opacity: 1;
}
.icon-button {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 6px;
  color: var(--ink);
  background: #323a2c;
  transition: background 160ms ease-out;
}
.icon-button:hover {
  background: #424d36;
}
.icon-button:active {
  background: #566344;
}
.result {
  margin-top: 12px;
}
.share-link {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
  text-decoration: none;
}
.share-link span {
  overflow-wrap: anywhere;
}
.share-link svg {
  flex-shrink: 0;
  color: var(--accent);
}
.share-link:hover {
  color: var(--ink);
  text-decoration: underline;
}
.primary-button {
  width: 100%;
  min-height: 42px;
  margin-top: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 0;
  border-radius: 9px;
  color: #1c2410;
  background: var(--accent);
  font-size: 13px;
  font-weight: 750;
  transition: background 150ms ease-out;
}
.primary-button:hover {
  background: #e7ff9e;
}
.primary-button:active {
  background: #c9e66b;
}
.primary-button[data-state="copied"] {
  background: #c5e28a;
}
.status,
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.status[data-state="error"] {
  position: static;
  width: auto;
  height: auto;
  margin: 12px 0 0;
  overflow: visible;
  clip-path: none;
  white-space: normal;
  color: var(--error);
  font-size: 12px;
  line-height: 1.5;
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    /* biome-ignore lint/complexity/noImportantStyles: accessibility preferences override control transitions. */
    transition: none !important;
  }
}
